window.POETRY_REGISTER("v5-strict-14-14-0-7bd0ebee86f8.js",{"poems":[[49184,2],[49185,2],[51995,2],[143395,7],[143405,7],[233445,7],[271711,7],[285959,7],[293620,7],[650074,5],[663738,5]],"pairs":[["岂不闻乎天地于道德也无以清宁","岂不闻乎道德于天地也有逾绳墨",0],["吾所以思抗迹忘机用虚无为师范","吾所以思去奢灭欲保道德为规箴",1],["主要是在龙虎山茅山天台山之间","李翔大概就是这一地区以内的人",2],["不然将吾颜子箪食瓢饮屡空之乐","又欲翻董生清明玉杯繁露之春秋",3],["抑其不得不然兮或者私智之所设","将忽然而自尔兮遂已成而不可绝",4],["酌瑶尊之芳酒兮招赤松而友彭祖","既锡我以难老兮黜嗜欲而袭灵虚",4],["杀竹枝而求泪班兮思二妃之矩度","哀灵修之返无期兮荪舍兹将安寓",5],["我不能苦身刻骨为名抵死求媚妩","又不能南柯北牖指梦所历为喜怒",6],["大小藏蕴灵异兮下有龙湫水泠泠","一线天通九有兮旁有风洞凉凄凄",7],["峙凌虚金碧兮增飞来小朶之奇观","发昔人幽潜兮来典午咸和之遗芳",8],["那萧衍有学问的英雄偏收了侯景","不料他是掘尾巴的恶狗乱了朝纲",9],["我不能学春城无处不飞花之韩翃","亦无才儗小楼一夜听春雨之放翁",10]]});
